#include <string>
#include <vector>
#include <algorithm>
using namespace std;

class Hospital; // forward declaration

class Doctor {
public:
    string name;
    vector<Hospital*> hospitals;

    void joinHospital(Hospital* hospital);
};

class Hospital {
public:
    string name;
    vector<Doctor*> doctors;

    void addDoctor(Doctor* doctor) {
        if (find(doctors.begin(), doctors.end(), doctor) == doctors.end()) {
            doctors.push_back(doctor);
            doctor->joinHospital(this);
        }
    }
};

void Doctor::joinHospital(Hospital* hospital) {
    if (find(hospitals.begin(), hospitals.end(), hospital) == hospitals.end()) {
        hospitals.push_back(hospital);
        hospital->addDoctor(this);
    }
}

